/**
 * Guards for noUncheckedIndexedAccess (record/array index may be undefined).
 */

export function arrayAt<T>(arr: readonly T[], index: number): T | undefined {
    return arr[index];
}

export function recordGet<K extends string, V>(
    record: Readonly<Record<K, V>>,
    key: K | undefined
): V | undefined {
    if (key === undefined) return undefined;
    return record[key];
}

export function recordGetOr<K extends string, V>(
    record: Readonly<Record<K, V>>,
    key: K | undefined,
    fallback: V
): V {
    if (key === undefined) return fallback;
    return record[key] ?? fallback;
}
