/**
 * @file eggRegionMap.ts
 * National Dex → région d'origine pour le tirage des œufs uniquement (pas les zones sauvages).
 * Les déblocages suivent la progression régionale réelle (maxReached valide par région).
 * Phase 5.4 — @ts-nocheck removed, full typing.
 */

import type { GameRuntime } from '../../src/types/game.js';
import { isEggRegionUnlockedForGame } from '../../src/lib/regionUnlock.ts';

export { isEggRegionUnlockedForGame };
import { POKEMON_SPRITE_IDS as _POKEMON_SPRITE_IDS } from './dexAndCapture.js';

const POKEMON_SPRITE_IDS = _POKEMON_SPRITE_IDS as Record<string, number>;

/** Pondération appliquée aux espèces dont la région d'origine = région courante du joueur. */
export const EGG_CURRENT_REGION_WEIGHT_MULTIPLIER = 2.5;

interface DexRegionThreshold {
    maxDex: number;
    regionId: string;
}

/** Seuils National Dex (inclus) → id de région aligné sur REGIONS / ZONES du projet. */
export const EGG_DEX_REGION_THRESHOLDS: DexRegionThreshold[] = [
    { maxDex: 151, regionId: 'kanto' },
    { maxDex: 251, regionId: 'johto' },
    { maxDex: 386, regionId: 'hoenn' },
    { maxDex: 493, regionId: 'sinnoh' },
    { maxDex: 649, regionId: 'unova' },
    { maxDex: 721, regionId: 'kalos' },
    { maxDex: 809, regionId: 'alola' },
    { maxDex: 898, regionId: 'galar' },
    { maxDex: 1025, regionId: 'paldea' }
];

export function getEggNativeRegionIdForNationalDex(dexId: number | string): string | null {
    const id = Number(dexId);
    if (!Number.isFinite(id) || id < 1) return null;
    for (let i = 0; i < EGG_DEX_REGION_THRESHOLDS.length; i++) {
        const threshold = EGG_DEX_REGION_THRESHOLDS[i];
        if (!threshold) continue;
        if (id <= threshold.maxDex) return threshold.regionId;
    }
    return EGG_DEX_REGION_THRESHOLDS[EGG_DEX_REGION_THRESHOLDS.length - 1]?.regionId ?? null;
}

export function getEggNativeRegionIdForSpecies(speciesName: string | null | undefined): string | null {
    if (!speciesName) return null;
    const dex = Number(POKEMON_SPRITE_IDS[speciesName]);
    return getEggNativeRegionIdForNationalDex(dex);
}

/**
 * Filtre les noms d'espèces : uniquement celles dont la région d'origine est déjà débloquée.
 * Espèce sans dex valide → traitée comme Kanto (toujours débloqué) pour compatibilité données.
 */
export function filterEggSpeciesNamesForProgress(game: GameRuntime | null | undefined, allNames: string[]): string[] {
    if (!Array.isArray(allNames) || allNames.length === 0) return allNames;
    if (!game) return [];
    const filtered: string[] = [];
    for (let i = 0; i < allNames.length; i++) {
        const name = allNames[i];
        if (name == null) continue;
        const native = getEggNativeRegionIdForSpecies(name);
        const unlockKey = native || 'kanto';
        if (isEggRegionUnlockedForGame(game, unlockKey)) filtered.push(name);
    }
    return filtered;
}

function pickWeightedIndex(weights: number[]): number {
    let total = 0;
    for (let i = 0; i < weights.length; i++) total += Math.max(0, Number(weights[i]) || 0);
    if (total <= 0) return 0;
    let roll = Math.random() * total;
    for (let j = 0; j < weights.length; j++) {
        roll -= Math.max(0, Number(weights[j]) || 0);
        if (roll <= 0) return j;
    }
    return weights.length - 1;
}

/**
 * Choisit une espèce dans le pool de rareté : filtrage régional + boost région courante + radar Pokédex.
 * Si le filtre vide le pool, retourne null (repli sûr côté appelant).
 */
export function pickEggSpeciesFromPool(
    game: GameRuntime | null | undefined,
    allNames: string[],
    radarTargets: string[],
): string | null {
    if (!Array.isArray(allNames) || allNames.length === 0) return null;

    const radar: string[] = Array.isArray(radarTargets) ? radarTargets : [];
    const hasGame = typeof game !== 'undefined' && game !== null;

    const pool = hasGame ? filterEggSpeciesNamesForProgress(game, allNames) : [];
    if (pool.length === 0) return null;

    const g = game as Record<string, unknown> | null | undefined;
    const currentRegionId = hasGame && typeof g?.getCurrentRegionId === 'function'
        ? String((g.getCurrentRegionId as () => unknown)())
        : 'kanto';

    const focusRegionId = hasGame && typeof g?.getRegionalFocusRegionId === 'function'
        ? (g.getRegionalFocusRegionId as () => unknown)() as string | null
        : null;
    const focusWeightBonus = (hasGame && typeof g?.getMasteryBonus === 'function' && (g.getMasteryBonus as (k: string) => number)('regional_focus') > 0)
        ? (g.getMasteryBonus as (k: string) => number)('regional_focus')
        : 0;

    const rm = hasGame && typeof g?.getPokedexRadarWeightMultiplier === 'function'
        ? ((g.getPokedexRadarWeightMultiplier as () => number)() || 1)
        : 3;

    const weights = pool.map((n) => {
        let w = 1;
        const native = getEggNativeRegionIdForSpecies(n);
        if (native && native === currentRegionId) {
            w *= EGG_CURRENT_REGION_WEIGHT_MULTIPLIER;
        }
        if (focusWeightBonus > 0 && focusRegionId && native && native === focusRegionId) {
            w *= (1 + focusWeightBonus);
        }
        if (radar.indexOf(n) !== -1) w *= rm;
        return w;
    });

    const idx = pickWeightedIndex(weights);
    return pool[idx] ?? null;
}

