/**
 * Shared region unlock checks (zone selector, egg hatch filter).
 * Kept separate from zoneSystem to avoid eggRegionMap ↔ zoneSystem circular imports.
 */
import type { GameRuntime } from '../types/game.js';
import { currentZone, maxReachedZoneByRegion } from '../../gameManager.ts';
import { isRegionReleased, RELEASED_REGION_IDS } from '../../constants/balance/regionRelease.ts';
import { REGIONAL_RESONANCE } from '../../constants/balance/regionalResonance.ts';
import { ZONES } from '../../constants/balance/zonesAndPacing.ts';
import { hasRegionalStarterCommitment } from './regionalResonance.ts';
import { arrayAt } from './safeAccess.ts';

type ZoneEntry = { regionId?: string; regionOrder?: number; unlockRequirement?: string };

const zones = ZONES as Record<number, ZoneEntry>;

function getZoneRegionId(zoneId: number): string {
    const zId = Number(zoneId);
    const zone = Number.isFinite(zId) ? zones[zId] : null;
    return zone?.regionId ? String(zone.regionId) : 'kanto';
}

function getSortedZoneIdsForRegion(regionId: string): number[] {
    const target = String(regionId || 'kanto');
    return Object.keys(zones)
        .map((id) => Number(id))
        .filter((id) => Number.isFinite(id) && getZoneRegionId(id) === target)
        .sort((a, b) => {
            const za = zones[a];
            const zb = zones[b];
            const oa = Number(za?.regionOrder);
            const ob = Number(zb?.regionOrder);
            if (Number.isFinite(oa) && Number.isFinite(ob) && oa !== ob) return oa - ob;
            return a - b;
        });
}

function getFirstZoneIdForRegion(regionId: string): number | null {
    return arrayAt(getSortedZoneIdsForRegion(regionId), 0) ?? null;
}

function hasBadgeFlag(game: GameRuntime, badgeKey: string): boolean {
    if (!game || !badgeKey) return false;
    if (typeof game.hasBadge === 'function') return game.hasBadge(badgeKey);
    return !!(game.badges && game.badges[badgeKey]);
}

function meetsZoneUnlockRequirement(game: GameRuntime, zoneId: number): boolean {
    const zone = zones[zoneId];
    if (!zone || !zone.unlockRequirement) return true;
    const req = String(zone.unlockRequirement);
    if (req.indexOf('badge:') === 0) {
        const badge = req.slice('badge:'.length);
        const hasBadge = hasBadgeFlag(game, badge);
        if (!hasBadge && badge === 'maitre_kanto') {
            const leagueQuestDone = Array.isArray(game.completedStoryQuests)
                && game.completedStoryQuests.indexOf('story_elite_four') !== -1;
            const badgesEarned = Number(game.stats?.badgesEarned);
            const arenasWon = Number(game.stats?.arenasWon);
            const eliteLikelyDone = (Number.isFinite(badgesEarned) && badgesEarned >= 9)
                || (Number.isFinite(arenasWon) && arenasWon >= 9);
            if (leagueQuestDone || eliteLikelyDone) {
                if (game.badges) game.badges.maitre_kanto = true;
                if (game.stats) {
                    const totalBadges = Object.values(game.badges || {}).filter((v) => v === true).length;
                    if (Number.isFinite(totalBadges) && totalBadges > 0) game.stats.badgesEarned = totalBadges;
                }
                return true;
            }
        }
        return hasBadge;
    }
    if (req.indexOf('arena:') === 0) {
        const arenaId = parseInt(req.slice('arena:'.length), 10);
        if (!Number.isFinite(arenaId) || arenaId <= 0) return false;
        return typeof game.isArenaUnlocked === 'function' && game.isArenaUnlocked(String(arenaId));
    }
    return true;
}

/** Same rules as zoneSystem._isRegionUnlocked (released regions + progression). */
export function isRegionUnlockedForGame(game: GameRuntime, regionId: string): boolean {
    const rid = regionId ? String(regionId) : 'kanto';
    if (!isRegionReleased(rid)) return false;
    if (rid === 'kanto') return true;
    const firstZoneId = getFirstZoneIdForRegion(rid);
    if (!firstZoneId) return false;
    if (meetsZoneUnlockRequirement(game, firstZoneId)) return true;
    return hasValidRegionalProgress(rid);
}

function hasValidRegionalProgress(regionId: string): boolean {
    const rid = String(regionId || 'kanto');
    const progress = Number(maxReachedZoneByRegion?.[rid]);
    if (!Number.isFinite(progress) || progress <= 0) return false;
    const zone = zones[progress];
    return !!(zone && getZoneRegionId(progress) === rid);
}

function zoneBelongsToRegion(zoneId: number, regionId: string): boolean {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId) || zId <= 0) return false;
    return getZoneRegionId(zId) === String(regionId || 'kanto');
}

/** Persist a region visit (survives maxReached sanitization and save/load). */
export function markPlayerRegionVisited(
    game: GameRuntime | null | undefined,
    regionId: string,
): void {
    const rid = regionId ? String(regionId) : 'kanto';
    if (!game || !rid) return;
    if (!game.regionsVisited || typeof game.regionsVisited !== 'object') {
        game.regionsVisited = {};
    }
    game.regionsVisited[rid] = true;
}

const REGION_START_STORY_QUEST_ID_RE = /^story_(sinnoh|unova|kalos|alola|galar)_start$/;

/**
 * Welcome-to-region story quests: only count an explicit player visit (region/zone selector travel),
 * not badge unlock or maxReached inferred from progression repair.
 */
export function hasPlayerSelectedRegionForWelcomeQuest(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    const rid = regionId ? String(regionId) : 'kanto';
    if (!game?.regionsVisited || typeof game.regionsVisited !== 'object') return false;
    return game.regionsVisited[rid] === true;
}

/** Backfill persistent visit flags from save progress (completed welcome quests + legacy starter commitment). */
export function backfillRegionsVisitedFromSaveProgress(game: GameRuntime | null | undefined): void {
    if (!game) return;
    if (!game.regionsVisited || typeof game.regionsVisited !== 'object') {
        game.regionsVisited = {};
    }
    const store = game.regionsVisited;
    const completed = game.completedStoryQuests;
    if (Array.isArray(completed)) {
        for (const questId of completed) {
            const match = String(questId).match(REGION_START_STORY_QUEST_ID_RE);
            if (match?.[1]) store[match[1]] = true;
        }
    }
    // Legacy saves before regionsVisited: starter picked + valid maxReached implies a real visit.
    Object.keys(maxReachedZoneByRegion || {}).forEach((regionId) => {
        if (regionId === 'kanto' || store[regionId]) return;
        if (!hasValidRegionalProgress(regionId)) return;
        if (!hasRegionalStarterCommitment(game, regionId)) return;
        store[regionId] = true;
    });
}

/** Clear visit flags inferred from badge unlock while a welcome quest is still pending. */
export function resetFalseRegionsVisitedForPendingWelcomeQuests(game: GameRuntime | null | undefined): void {
    if (!game?.regionsVisited || typeof game.regionsVisited !== 'object') return;
    if (!Array.isArray(game.quests)) return;
    for (const quest of game.quests) {
        if (quest.completed || quest.claimed) continue;
        const id = String((quest as { id?: string | number }).id || '');
        const match = id.match(REGION_START_STORY_QUEST_ID_RE);
        if (!match?.[1]) continue;
        const reqRegion = (quest as { specialParams?: { requiredRegion?: string } }).specialParams?.requiredRegion
            || match[1];
        if (!reqRegion || !game.regionsVisited[reqRegion]) continue;
        if (hasRegionalStarterCommitment(game, reqRegion)) continue;
        delete game.regionsVisited[reqRegion];
    }
}

/**
 * True when the player has actually traveled to at least one zone in the region
 * (persistent flag, maxReached, current zone, or session zone visits).
 */
export function hasPlayerVisitedRegionForGame(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    const rid = regionId ? String(regionId) : 'kanto';
    if (!game) return false;
    if (game.regionsVisited && game.regionsVisited[rid]) return true;
    if (hasValidRegionalProgress(rid)) return true;
    if (zoneBelongsToRegion(Number(currentZone), rid)) return true;
    const visited = game.sessionStats?.zonesVisited;
    if (visited instanceof Set) {
        for (const zoneId of visited) {
            if (zoneBelongsToRegion(Number(zoneId), rid)) return true;
        }
    }
    return false;
}

function hasRegionalMasterBadge(game: GameRuntime, regionId: string): boolean {
    const badgeKey = REGIONAL_RESONANCE.masterBadgeByRegion[regionId];
    if (!badgeKey) return false;
    if (typeof game.hasBadge === 'function') return game.hasBadge(badgeKey);
    const badges = game.badges as Record<string, boolean> | undefined;
    return !!(badges && badges[badgeKey]);
}

/** True when a later released region has valid egg progress (unlocks prior regions for eggs). */
function hasEggAccessViaLaterRegionProgress(game: GameRuntime, regionId: string): boolean {
    const rid = String(regionId || 'kanto');
    const order = RELEASED_REGION_IDS as readonly string[];
    const idx = order.indexOf(rid);
    if (idx < 0) return false;
    for (let i = idx + 1; i < order.length; i++) {
        const later = order[i];
        if (!later || !isRegionReleased(later)) continue;
        if (hasValidRegionalProgress(later) && hasRegionalStarterCommitment(game, later)) {
            return true;
        }
    }
    return false;
}

/**
 * Egg pools unlock with regional progress + starter commitment, master badge, or later-region progress.
 */
export function isEggRegionUnlockedForGame(game: GameRuntime | null | undefined, regionId: string): boolean {
    if (!game) return false;
    const rid = regionId ? String(regionId) : 'kanto';
    if (rid === 'kanto') return true;
    if (!isRegionReleased(rid)) return false;
    if (hasRegionalMasterBadge(game, rid)) return true;
    if (hasEggAccessViaLaterRegionProgress(game, rid)) return true;
    return hasValidRegionalProgress(rid)
        && hasRegionalStarterCommitment(game, rid);
}

/** Zero maxReached for resonance regions before regional starter commitment. */
export function sanitizeRegionalProgressWithoutStarterCommitment(
    game: GameRuntime | null | undefined,
    store: Record<string, number> | null | undefined,
): void {
    if (!game || !store || typeof store !== 'object') return;
    const regionIds = new Set<string>();
    Object.keys(store).forEach((r) => regionIds.add(r));
    Object.keys(zones).forEach((idStr) => {
        const id = Number(idStr);
        if (Number.isFinite(id)) regionIds.add(getZoneRegionId(id));
    });

    regionIds.forEach((regionId) => {
        if (regionId === 'kanto' || !isRegionReleased(regionId)) return;
        const currentVal = Number(store[regionId]);
        if (!Number.isFinite(currentVal) || currentVal <= 0) return;
        if (!hasRegionalStarterCommitment(game, regionId)) {
            store[regionId] = 0;
        }
    });
}

/** Reset maxReached when the stored zone id belongs to another region (e.g. hoenn: 144). */
export function sanitizeCrossRegionMaxReachedPollution(
    store: Record<string, number> | null | undefined,
): void {
    if (!store || typeof store !== 'object') return;
    const regionIds = new Set<string>();
    Object.keys(store).forEach((r) => regionIds.add(r));
    Object.keys(zones).forEach((idStr) => {
        const id = Number(idStr);
        if (Number.isFinite(id)) regionIds.add(getZoneRegionId(id));
    });

    regionIds.forEach((regionId) => {
        if (regionId === 'kanto') return;
        const firstZoneId = getFirstZoneIdForRegion(regionId);
        const currentVal = Number(store[regionId]);
        if (!Number.isFinite(currentVal)) {
            store[regionId] = 0;
        } else if (currentVal < 0) {
            store[regionId] = 0;
        } else if (firstZoneId && currentVal > 0 && (!zones[currentVal] || getZoneRegionId(currentVal) !== regionId)) {
            store[regionId] = 0;
        }
    });
}

/** Zero maxReached when the player has not met the region entry badge (e.g. hoenn without maitre_johto). */
export function sanitizeRegionalProgressWithoutEntryBadge(
    game: GameRuntime | null | undefined,
    store: Record<string, number> | null | undefined,
): void {
    if (!game || !store || typeof store !== 'object') return;
    const regionIds = new Set<string>();
    Object.keys(store).forEach((r) => regionIds.add(r));
    Object.keys(zones).forEach((idStr) => {
        const id = Number(idStr);
        if (Number.isFinite(id)) regionIds.add(getZoneRegionId(id));
    });

    regionIds.forEach((regionId) => {
        if (regionId === 'kanto' || !isRegionReleased(regionId)) return;
        const currentVal = Number(store[regionId]);
        if (!Number.isFinite(currentVal) || currentVal <= 0) return;
        const firstZoneId = getFirstZoneIdForRegion(regionId);
        if (!firstZoneId) return;
        if (!meetsZoneUnlockRequirement(game, firstZoneId)) {
            store[regionId] = 0;
        }
    });
}

/** Zero maxReached for regions not in the current public build. */
export function sanitizeUnreleasedRegionProgress(
    store: Record<string, number> | null | undefined,
): void {
    if (!store || typeof store !== 'object') return;
    Object.keys(store).forEach((regionId) => {
        if (!isRegionReleased(regionId)) {
            store[regionId] = 0;
        }
    });
}
