import { REGIONAL_RESONANCE } from '../../constants/balance/regionalResonance.ts';
import {
    EGG_DEX_REGION_THRESHOLDS,
    getEggNativeRegionIdForSpecies,
} from '../../constants/balance/eggRegionMap.ts';
import { EVOLUTION_FAMILIES } from '../../constants/evolutionFamilies.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import { getPokemonSpriteUrl } from './cardSprites.ts';
