export type ResonanceCap = {
    prestige: number;
    level: number;
    simulatedLevel: number;
    anchorCount: number;
};

export type EffectivePrestigeLevel = {
    prestige: number;
    level: number;
    capped: boolean;
    resonanceActive: boolean;
};

export type ResonanceAnchorPreview = {
    uid: string;
    name: string;
    displayName: string;
    spriteUrl: string;
    prestige: number;
    level: number;
    simulatedLevel: number;
};

export type ResonanceTeamPreview = {
    active: boolean;
    regionId: string;
    capSimLevel: number;
    capPrestige: number;
    capLevel: number;
    /** Top previewAnchorTopN — inline bandeau équipe. */
    anchors: ResonanceAnchorPreview[];
    /** Top anchorTopN — tooltip complet (sprites + lignes). */
    tooltipAnchors: ResonanceAnchorPreview[];
};

type ResonanceCapCache = {
    regionId: string;
    cap: ResonanceCap;
    /** Anchor-only roster fingerprint (stable uid sort). */
    rosterKey: string;
    /** Top anchorTopN regional anchors (sorted desc), shared with preview build. */
    sortedAnchors: CreatureData[];
    preview: ResonanceTeamPreview | null;
};

type AccountBenchmarkCache = {
    regionId: string;
    topN: number;
    rosterKey: string;
    value: number;
};

/** Max level at a given prestige tier (matches Creature.getMaxLevel). */
export function getMaxLevelForPrestige(prestige: number): number {
    const p = Math.max(0, Math.floor(Number(prestige) || 0));
    return 100 + p * 10;
}

/** Total progression index: current level + sum of completed prestige level caps. */
export function computeSimulatedLevel(prestige: number, level: number): number {
    const p = Math.max(0, Math.floor(Number(prestige) || 0));
    const lv = Math.max(0, Math.floor(Number(level) || 0));
    let sum = lv;
    for (let i = 0; i < p; i++) {
        sum += getMaxLevelForPrestige(i);
    }
    return sum;
}

/** Inverse of computeSimulatedLevel — prestige + level for combat stats. */
export function decomposeSimulatedLevel(simLevel: number): { prestige: number; level: number } {
    const target = Math.max(1, Math.floor(Number(simLevel) || 0));
    let remaining = target;
    let prestige = 0;
    while (true) {
        const maxForTier = getMaxLevelForPrestige(prestige);
        if (remaining <= maxForTier) {
            return { prestige, level: remaining };
        }
        remaining -= maxForTier;
        prestige++;
    }
}

export function computeResonanceCapFromAnchors(anchors: CreatureData[]): ResonanceCap {
    const fallback = REGIONAL_RESONANCE.fallbackCap;
    if (!anchors.length) {
        return {
            prestige: fallback.prestige,
            level: fallback.level,
            simulatedLevel: fallback.simulatedLevel,
            anchorCount: 0,
        };
    }
    const topN = anchors.slice(0, REGIONAL_RESONANCE.anchorTopN);
    const totalSim = topN.reduce(
        (acc, c) => acc + computeSimulatedLevel(Number(c.prestige) || 0, Number(c.level) || 0),
        0,
    );
    const capSimLevel = Math.floor(totalSim / topN.length);
    const { prestige, level } = decomposeSimulatedLevel(capSimLevel);
    return {
        prestige,
        level,
        simulatedLevel: capSimLevel,
        anchorCount: topN.length,
    };
}

export function getRegionDexRange(regionId: string): { minDex: number; maxDex: number } | null {
    const id = String(regionId || '');
    const thresholds = EGG_DEX_REGION_THRESHOLDS;
    let prevMax = 0;
    for (let i = 0; i < thresholds.length; i++) {
        const entry = thresholds[i];
        if (!entry || entry.regionId !== id) continue;
        return { minDex: prevMax + 1, maxDex: entry.maxDex };
    }
    return null;
}

export function dexBelongsToRegion(speciesName: string, regionId: string): boolean {
    const native = getEggNativeRegionIdForSpecies(resolveCanonicalSpeciesName(speciesName));
    return native === String(regionId || '');
}

export function getEvolutionFamilyRoot(speciesName: string): string {
    const key = resolveCanonicalSpeciesName(speciesName);
    if (Object.prototype.hasOwnProperty.call(EVOLUTION_FAMILIES, key)) {
        return EVOLUTION_FAMILIES[key as keyof typeof EVOLUTION_FAMILIES];
    }
    return key;
}

/** Species whose dex and evolution-family root both belong to the regional arc. */
export function isPureRegionalSpecies(speciesName: string, regionId: string): boolean {
    if (!dexBelongsToRegion(speciesName, regionId)) return false;
    const root = getEvolutionFamilyRoot(speciesName);
    return dexBelongsToRegion(root, regionId);
}

export function inferRegionalArcId(creature: CreatureData): string {
    const saved = creature.regionalArcId;
    if (typeof saved === 'string' && saved.length > 0) return saved;
    return getEggNativeRegionIdForSpecies(resolveCanonicalSpeciesName(creature.name)) ?? 'kanto';
}

export function assignRegionalArcId(creature: CreatureData, regionId: string): void {
    creature.regionalArcId = String(regionId || 'kanto');
}

export function inheritRegionalArcId(creature: CreatureData, parent: CreatureData): void {
    creature.regionalArcId = inferRegionalArcId(parent);
}

/** Anchor = pure regional dex species (native region + evolution root), not obtain location. */
export function isResonanceAnchor(creature: CreatureData, regionId: string): boolean {
    return isPureRegionalSpecies(creature.name, regionId);
}

export function isVeteranSubjectToResonance(creature: CreatureData, regionId: string): boolean {
    return !isResonanceAnchor(creature, regionId);
}

function getGameRegionId(game: GameRuntime | null | undefined): string {
    if (!game) return 'kanto';
    if (typeof game.getCurrentRegionId === 'function') {
        return String(game.getCurrentRegionId() || 'kanto');
    }
    if (typeof game.currentRegion === 'string' && game.currentRegion) {
        return game.currentRegion;
    }
    return 'kanto';
}

function hasRegionalMasterBadge(game: GameRuntime, regionId: string): boolean {
    const badgeKey = REGIONAL_RESONANCE.masterBadgeByRegion[regionId];
    if (!badgeKey) return false;
    if (typeof game.hasBadge === 'function') return game.hasBadge(badgeKey);
    const badges = game.badges as Record<string, boolean> | undefined;
    return !!(badges && badges[badgeKey]);
}

/**
 * True when regional egg pools / travel progression may treat this region as begun:
 * Kanto and non-resonance regions always; resonance regions after starter pick or league master title.
 */
export function hasRegionalStarterCommitment(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    if (!game) return false;
    const region = String(regionId || 'kanto').toLowerCase();
    if (region === 'kanto') return true;
    if (!REGIONAL_RESONANCE.enabled) return true;
    if (!(REGIONAL_RESONANCE.enabledRegionIds as readonly string[]).includes(region)) {
        return true;
    }
    if (hasRegionalMasterBadge(game, region)) return true;
    return !!(game.regionalStarterOffered && game.regionalStarterOffered[region]);
}

export function isRegionalResonanceActive(
    game: GameRuntime | null | undefined,
    regionId?: string,
): boolean {
    if (!REGIONAL_RESONANCE.enabled || !game) return false;
    const region = regionId ?? getGameRegionId(game);
    if (!(REGIONAL_RESONANCE.enabledRegionIds as readonly string[]).includes(region)) return false;
    if (getGameRegionId(game) !== region) return false;
    return !hasRegionalMasterBadge(game, region);
}

export function shouldShowResonanceIntro(
    game: GameRuntime | null | undefined,
    regionId: string,
): boolean {
    if (!game || game.resonanceIntroShown) return false;
    const region = String(regionId || '');
    if (!(REGIONAL_RESONANCE.enabledRegionIds as readonly string[]).includes(region)) {
        return false;
    }
    return isRegionalResonanceActive(game, region);
}

/** Region id for post-load resonance catch-up, or null when not applicable. */
export function getRegionalResonanceCatchUpRegionId(
    game: GameRuntime | null | undefined,
): string | null {
    if (!game || !REGIONAL_RESONANCE.enabled) return null;
    const region = typeof game.getCurrentRegionId === 'function'
        ? String(game.getCurrentRegionId() || '')
        : String(game.currentRegion || '');
    if (!REGIONAL_RESONANCE.startersByRegion[region]) return null;
    return region;
}

export function collectOwnedCreatures(game: GameRuntime): CreatureData[] {
    const out: CreatureData[] = [];
    const push = (list: CreatureData[] | undefined) => {
        if (!Array.isArray(list)) return;
        for (let i = 0; i < list.length; i++) {
            const c = list[i];
            if (c && !c.isEnemy) out.push(c);
        }
    };
    push(game.playerTeam);
    push(game.storage);
    push(game.pension);
    push(game.miltankFarmState?.pastureCreatures);
    const expeditions = game.activeExpeditions;
    if (Array.isArray(expeditions)) {
        for (let e = 0; e < expeditions.length; e++) {
            const exp = expeditions[e];
            if (!exp) continue;
            if (Array.isArray(exp.squadData)) {
                push(exp.squadData as CreatureData[]);
            } else if (exp.creatureData) {
                const c = exp.creatureData as CreatureData;
                if (c && !c.isEnemy) out.push(c);
            }
        }
    }
    return out;
}

function anchorRosterCacheKey(regionId: string, anchors: CreatureData[]): string {
    const parts = anchors.map((c) => {
        const uid = typeof c.uid === 'string' ? c.uid : c.name;
        const p = Number(c.prestige) || 0;
        const lv = Number(c.level) || 0;
        return `${uid}:${p}:${lv}`;
    });
    parts.sort();
    return `${regionId}|${parts.join(';')}`;
}

function getCapCache(game: GameRuntime): ResonanceCapCache | undefined {
    return (game as GameRuntime & { _resonanceCapCache?: ResonanceCapCache })._resonanceCapCache;
}

function setCapCache(game: GameRuntime, cache: ResonanceCapCache | undefined): void {
    (game as GameRuntime & { _resonanceCapCache?: ResonanceCapCache })._resonanceCapCache = cache;
}

function getBenchmarkCache(game: GameRuntime): AccountBenchmarkCache | undefined {
    return (game as GameRuntime & { _accountBenchmarkCache?: AccountBenchmarkCache })._accountBenchmarkCache;
}

function setBenchmarkCache(game: GameRuntime, cache: AccountBenchmarkCache | undefined): void {
    (game as GameRuntime & { _accountBenchmarkCache?: AccountBenchmarkCache })._accountBenchmarkCache = cache;
}

function ownedRosterCacheKey(owned: CreatureData[]): string {
    const parts = owned.map((c) => {
        const uid = typeof c.uid === 'string' ? c.uid : c.name;
        const p = Number(c.prestige) || 0;
        const lv = Number(c.level) || 0;
        return `${uid}:${p}:${lv}`;
    });
    parts.sort();
    return parts.join(';');
}

export function invalidateResonanceCache(game: GameRuntime | null | undefined): void {
    if (!game) return;
    setCapCache(game, undefined);
    setBenchmarkCache(game, undefined);
}

function sortAnchorsDesc(a: CreatureData, b: CreatureData): number {
    const pa = Number(a.prestige) || 0;
    const pb = Number(b.prestige) || 0;
    if (pb !== pa) return pb - pa;
    const la = Number(a.level) || 0;
    const lb = Number(b.level) || 0;
    if (lb !== la) return lb - la;
    const ua = typeof a.uid === 'string' ? a.uid : a.name;
    const ub = typeof b.uid === 'string' ? b.uid : b.name;
    return ua.localeCompare(ub);
}

function rebuildResonanceCapCache(game: GameRuntime, region: string): ResonanceCapCache {
    const anchors = collectOwnedCreatures(game)
        .filter((c) => isResonanceAnchor(c, region))
        .sort(sortAnchorsDesc);
    const cap = computeResonanceCapFromAnchors(anchors);
    const topN = Math.max(1, Math.floor(Number(REGIONAL_RESONANCE.anchorTopN) || 1));
    const sortedAnchors = anchors.slice(0, Math.min(topN, anchors.length));
    return {
        regionId: region,
        cap,
        rosterKey: anchorRosterCacheKey(region, anchors),
        sortedAnchors,
        preview: null,
    };
}

export function getResonanceCap(
    game: GameRuntime | null | undefined,
    regionId?: string,
): ResonanceCap {
    const fallback = REGIONAL_RESONANCE.fallbackCap;
    if (!game) {
        return {
            prestige: fallback.prestige,
            level: fallback.level,
            simulatedLevel: fallback.simulatedLevel,
            anchorCount: 0,
        };
    }
    const region = regionId ?? getGameRegionId(game);
    const cached = getCapCache(game);
    if (cached && cached.regionId === region) {
        return cached.cap;
    }
    setCapCache(game, rebuildResonanceCapCache(game, region));
    return getCapCache(game)!.cap;
}

function getCachedResonanceAnchors(game: GameRuntime, regionId: string): CreatureData[] {
    getResonanceCap(game, regionId);
    const cached = getCapCache(game);
    if (!cached || cached.regionId !== regionId) return [];
    return cached.sortedAnchors;
}

function isCreatureInPlayerTeam(creature: CreatureData, game: GameRuntime): boolean {
    const team = game.playerTeam;
    if (!Array.isArray(team) || !team.length) return false;
    if (creature.uid) {
        return team.some((c) => c && c.uid === creature.uid);
    }
    return team.includes(creature);
}

/** Battle Subway (and similar modes): full raw stats, no regional resonance cap. */
export function isResonanceSuppressedForCombat(game: GameRuntime | null | undefined): boolean {
    if (!game) return false;
    const subway = game.subwayState as { isActive?: boolean } | undefined;
    return !!(subway && subway.isActive);
}

export function getEffectivePrestigeAndLevel(
    creature: CreatureData,
    game: GameRuntime | null | undefined,
    opts?: { inPlayerTeam?: boolean },
): EffectivePrestigeLevel {
    const realPrestige = Number(creature.prestige) || 0;
    const realLevel = Number(creature.level) || 1;
    if (!game || creature.isEnemy) {
        return {
            prestige: realPrestige,
            level: realLevel,
            capped: false,
            resonanceActive: false,
        };
    }
    if (isResonanceSuppressedForCombat(game)) {
        return {
            prestige: realPrestige,
            level: realLevel,
            capped: false,
            resonanceActive: false,
        };
    }
    const regionId = getGameRegionId(game);
    const resonanceActive = isRegionalResonanceActive(game, regionId);
    const inTeam = opts?.inPlayerTeam ?? isCreatureInPlayerTeam(creature, game);
    if (!resonanceActive || !inTeam || !isVeteranSubjectToResonance(creature, regionId)) {
        return {
            prestige: realPrestige,
            level: realLevel,
            capped: false,
            resonanceActive,
        };
    }
    const cap = getResonanceCap(game, regionId);
    const veteranSim = computeSimulatedLevel(realPrestige, realLevel);
    const cappedSim = Math.min(veteranSim, cap.simulatedLevel);
    const { prestige, level } = decomposeSimulatedLevel(cappedSim);
    return {
        prestige,
        level,
        capped: cappedSim < veteranSim,
        resonanceActive: true,
    };
}

export function getEffectivePrestige(creature: CreatureData, game: GameRuntime | null | undefined): number {
    return getEffectivePrestigeAndLevel(creature, game).prestige;
}

export function getEffectiveLevel(creature: CreatureData, game: GameRuntime | null | undefined): number {
    return getEffectivePrestigeAndLevel(creature, game).level;
}

/** Top-N for account benchmark: 6 × resonance arc rank (Johto=6, Hoenn=12, Sinnoh=18). */
export function getAccountBenchmarkTopN(regionId?: string): number {
    const perRegion = REGIONAL_RESONANCE.catchUp.accountBenchmarkTopNPerRegion ?? 6;
    const region = String(regionId || REGIONAL_RESONANCE.introRegionId || 'johto');
    const enabled = REGIONAL_RESONANCE.enabledRegionIds as readonly string[];
    const idx = enabled.indexOf(region);
    const rank = idx >= 0 ? idx + 1 : 1;
    return perRegion * rank;
}

/** Average simulated level of the top-N strongest owned Pokémon (N scales with active region). */
export function getAccountPowerBenchmark(
    game: GameRuntime | null | undefined,
    topN?: number,
): number {
    if (!game) return 0;
    const region = getGameRegionId(game);
    const n = Math.max(
        1,
        Math.floor(Number(topN ?? getAccountBenchmarkTopN(region)) || 1),
    );
    const owned = collectOwnedCreatures(game);
    if (!owned.length) return 0;
    const rosterKey = ownedRosterCacheKey(owned);
    const cached = getBenchmarkCache(game);
    if (
        cached
        && cached.regionId === region
        && cached.topN === n
        && cached.rosterKey === rosterKey
    ) {
        return cached.value;
    }
    const simLevels = owned
        .map((c) => computeSimulatedLevel(Number(c.prestige) || 0, Number(c.level) || 0))
        .sort((a, b) => b - a);
    const slice = simLevels.slice(0, Math.min(n, simLevels.length));
    const total = slice.reduce((acc, v) => acc + v, 0);
    const value = Math.floor(total / slice.length);
    setBenchmarkCache(game, { regionId: region, topN: n, rosterKey, value });
    return value;
}

/** Team-wide: 0 = anchor cap far below account elite; 1 = cap caught up to top-N benchmark. */
export function computeCatchUpXpProgress(
    game: GameRuntime | null | undefined,
    regionId?: string,
): number {
    if (!game) return 0;
    const region = regionId ?? getGameRegionId(game);
    const capSim = getResonanceCap(game, region).simulatedLevel;
    const benchmark = getAccountPowerBenchmark(game, getAccountBenchmarkTopN(region));
    if (benchmark <= 0) return 0;
    return Math.min(1, capSim / benchmark);
}

/** Per-anchor: 0 = far below account benchmark; 1 = caught up to top-N benchmark. */
export function computeCreatureCatchUpXpProgress(
    creature: CreatureData,
    game: GameRuntime | null | undefined,
    regionId?: string,
): number {
    if (!game) return 0;
    const region = regionId ?? getGameRegionId(game);
    const benchmark = getAccountPowerBenchmark(game, getAccountBenchmarkTopN(region));
    if (benchmark <= 0) return 0;
    const creatureSim = computeSimulatedLevel(
        Number(creature.prestige) || 0,
        Number(creature.level) || 0,
    );
    return Math.min(1, creatureSim / benchmark);
}

function computeDecayCatchUpXpMultFromProgress(progress: number): number {
    const maxMult = REGIONAL_RESONANCE.catchUp.xpMult;
    if (REGIONAL_RESONANCE.catchUp.xpDecayMode !== 'perAnchor') return maxMult;
    return 1 + (maxMult - 1) * (1 - progress);
}

export function getAnchorCatchUpXpMult(creature: CreatureData, game: GameRuntime | null | undefined): number {
    if (!game || !REGIONAL_RESONANCE.catchUp.activeWhileResonanceActive) return 1;
    if (!isRegionalResonanceActive(game)) return 1;
    const regionId = getGameRegionId(game);
    if (!isResonanceAnchor(creature, regionId)) return 1;
    const progress = computeCreatureCatchUpXpProgress(creature, game, regionId);
    const mult = computeDecayCatchUpXpMultFromProgress(progress);
    return mult <= 1 ? 1 : mult;
}

/** Prestige tier of the account top-N power benchmark (veteran average). */
export function getBenchmarkTargetPrestige(
    game: GameRuntime | null | undefined,
    regionId?: string,
): number {
    const region = regionId ?? (game ? getGameRegionId(game) : REGIONAL_RESONANCE.introRegionId);
    const benchmark = getAccountPowerBenchmark(game, getAccountBenchmarkTopN(region));
    if (benchmark <= 0) return 0;
    return decomposeSimulatedLevel(benchmark).prestige;
}

/** Binary gate: −1 stone while anchor prestige is below the veteran average prestige. */
export function anchorQualifiesForStoneDiscount(
    creature: CreatureData,
    game: GameRuntime | null | undefined,
    regionId?: string,
): boolean {
    const region = regionId ?? (game ? getGameRegionId(game) : REGIONAL_RESONANCE.introRegionId);
    const targetPrestige = getBenchmarkTargetPrestige(game, region);
    const anchorPrestige = Number(creature.prestige) || 0;

    if (targetPrestige > 0) {
        return anchorPrestige < targetPrestige;
    }
    return computeCreatureCatchUpXpProgress(creature, game, region) < 1;
}

export function getAnchorCatchUpPrestigeCosts(
    creature: CreatureData,
    game: GameRuntime | null | undefined,
    baseShards: number,
    baseStones: number,
): { shards: number; stones: number } {
    const shards = Math.max(1, Math.floor(Number(baseShards) || 1));
    const stones = Math.max(0, Math.floor(Number(baseStones) || 0));
    if (!game || !REGIONAL_RESONANCE.catchUp.activeWhileResonanceActive) {
        return { shards, stones };
    }
    if (!isRegionalResonanceActive(game)) return { shards, stones };
    const regionId = getGameRegionId(game);
    if (!isResonanceAnchor(creature, regionId)) return { shards, stones };
    const cfg = REGIONAL_RESONANCE.catchUp;
    const stoneDiscount = anchorQualifiesForStoneDiscount(creature, game, regionId)
        ? cfg.prestigeStoneDiscount
        : 0;
    return {
        shards: Math.max(1, Math.floor(shards * cfg.prestigeShardCostMult)),
        stones: Math.max(0, stones - stoneDiscount),
    };
}

export function migrateCreatureRegionalArcId(creature: CreatureData): void {
    creature.regionalArcId = inferRegionalArcId(creature);
}

export function migrateCreatureListRegionalArcId(list: CreatureData[] | undefined): void {
    if (!Array.isArray(list)) return;
    for (let i = 0; i < list.length; i++) {
        const c = list[i];
        if (c) migrateCreatureRegionalArcId(c);
    }
}

function toAnchorPreview(creature: CreatureData, game: GameRuntime): ResonanceAnchorPreview {
    const prestige = Number(creature.prestige) || 0;
    const level = Number(creature.level) || 1;
    const uid = typeof creature.uid === 'string' && creature.uid ? creature.uid : `${creature.name}|${prestige}`;
    return {
        uid,
        name: creature.name,
        displayName: uiPokemonName(game, creature.name),
        spriteUrl: getPokemonSpriteUrl(creature.name, !!creature.isShiny, false) || '',
        prestige,
        level,
        simulatedLevel: computeSimulatedLevel(prestige, level),
    };
}

function buildPreviewFromSortedAnchors(
    game: GameRuntime,
    regionId: string,
    cap: ResonanceCap,
    sortedAnchors: CreatureData[],
): ResonanceTeamPreview {
    const tooltipAnchors = sortedAnchors.map((c) => toAnchorPreview(c, game));
    const previewN = Math.max(1, Math.floor(Number(REGIONAL_RESONANCE.previewAnchorTopN) || 1));
    const anchors = tooltipAnchors.slice(0, Math.min(previewN, tooltipAnchors.length));
    return {
        active: true,
        regionId,
        capSimLevel: cap.simulatedLevel,
        capPrestige: cap.prestige,
        capLevel: cap.level,
        anchors,
        tooltipAnchors,
    };
}

export function buildResonanceTeamPreview(
    game: GameRuntime | null | undefined,
): ResonanceTeamPreview | null {
    if (!game || !REGIONAL_RESONANCE.enabled) return null;
    const regionId = getGameRegionId(game);
    if (!isRegionalResonanceActive(game, regionId)) return null;

    const cached = getCapCache(game);
    if (cached && cached.regionId === regionId && cached.preview) {
        return cached.preview;
    }

    const cap = getResonanceCap(game, regionId);
    const topForTooltip = getCachedResonanceAnchors(game, regionId);
    if (!topForTooltip.length) return null;

    const preview = buildPreviewFromSortedAnchors(game, regionId, cap, topForTooltip);
    const warm = getCapCache(game);
    if (warm && warm.regionId === regionId) {
        setCapCache(game, { ...warm, preview });
    }
    return preview;
}

/** Stable signature for TEAM_CHANGED dedup when anchor progression shifts. */
export function resonancePreviewSignature(preview: ResonanceTeamPreview | null | undefined): string {
    if (!preview || !preview.active) return '';
    const anchorParts = preview.tooltipAnchors
        .map((a) => `${a.uid}:${a.prestige}:${a.level}:${a.simulatedLevel}`)
        .join('|');
    return `${preview.regionId}:${preview.capSimLevel}:${preview.capPrestige}:${preview.capLevel}:${anchorParts}`;
}
